quests[8727] = { id = 8727, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Farwhisper the Elder", sourceObjective = "The heavens, in their countless stars, hold answers to earthly mysteries, {name}.  Might, then, the wise, and the lucky, gaze up and find truth?", sourceObjectiveStatus = "unverified-source-field" }
quests[8728] = { id = 8728, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Good News and The Bad News", description = "Well that took a little longer than expected. Now let me see what this ledger says.\n\n<Narain silently reads the ledger, periodically mumbling under his breath.>\n\n The good news is that I am 99% certain that I am capable of creating an arcanite buoy that will function to your specifications. This is, of course, wholly dependant on the bad news.\n\nThe bad news is that I'm going to need a lot of arcanite, elementium ore, and rare gemstones.\n\nBring me what I need and I will craft the buoy.", sourceObjective = "Narain Soothfancy in Tanaris wants you to bring him 20 Arcanite Bars, 10 Elementium Ore, 10 Azerothian Diamonds, and 10 Blue Sapphires.", progress = "Arcanite buoys don't just make themselves, {name}. And NO, you cannot borrow some money.", completion = "A deal is a deal. I sure hope you know what you are getting yourself into, {name}. This is an awful lot of trouble to go through to do some fishing.", sourceObjectiveStatus = "unverified-source-field" }
quests[8729] = { id = 8729, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Wrath of Neptulon", description = "Did I mention the bad news yet? Its name is Maws: 100 feet of death and destruction. I guess I may have forgotten that little tidbit.\n\nAccording to my superior psycho-psionic clairvoyance, you'll find that the best spot to cast this buoy is off the coast of Azshara, in the Bay of Storms.\n\nLook for a swirling maelstrom, most likely cluttered with wreckage.\n\nBy the by, I hope you have friends.\n\nNow if you somehow miraculously succeed, take the scepter shard to Anachronos.", sourceObjective = "Use the Arcanite Buoy at the Swirling Maelstrom at the Bay of Storms in Azshara.", progress = "Time is running out, champion.", completion = "Well done, {name}. I will be able to reform the Scepter of the Shifting Sands soon.", sourceObjectiveStatus = "unverified-source-field" }
quests[8730] = { id = 8730, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nefarius's Corruption", description = "Champion, is it you? A thousand years it has been since I was entrusted the shard and it is at my darkest hour that one should rise to relieve me of it... But what would tragedy be without cruelty?\n\n<Vaelastrasz coughs weakly.>\n\nNe... Nefarius now holds the scepter shard.\n\nTime is of the essence. Nefarius plans to destroy the shard. You must hurry!", sourceObjective = "Slay Nefarian and recover the Red Scepter Shard. Return the Red Scepter Shard to Anachronos at the Caverns of Time in Tanaris. You have 5 hours to complete this task.", progress = "Another of our heroes lost to the spawn of Deathwing. We will be cursed with this suffering forever...", completion = "Vaelastrasz's soul is at ease, champion. The Aspects all watch your progress with great interest. Know that you have powerful allies.\n\nI was commanded to grant you something to aid you in this struggle. Use it well...", sourceObjectiveStatus = "unverified-source-field" }
quests[8731] = { id = 8731, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Field Duty", description = "Greetings, {name}.  Before I assign you to more involved tasks in the war, you'll need to do your share of field duty.  \n\nYou will find Captain Skullsplit's Orgrimmar Legion outside Hive'Regal.\n\nReport to him and come back to me with proof of your field service.  I shall have a more advanced assignment ready for you.\n\nOh, please do your best to stay away from the Ironforge Brigade.  Tensions are high among our Alliance and Horde volunteers.", sourceObjective = "Report to Krug Skullsplit at the Orgrimmar Legion post in front of Hive'Regal. Prepare your Unsigned Field Duty Papers, obtain Signed Field Duty Papers and bring them to Windcaller Kaldon in Cenarion Hold.\n\nNote: Healing or casting beneficial spells on a member of the Orgrimmar Legion will flag you for PvP.", progress = "You've completed your field duty, {name}?  Captain Skullsplit can be found outside of Hive'Regal.", completion = "I can tell that Krug has little use for paperwork.  He signed this in silithid blood!\n\nVery well, {name}.  I've prepared a set of tasks that should make good use of your skills as a {class}.\n\nWith the continued efforts of you and people like you, our enemy will soon be crushed!", sourceObjectiveStatus = "unverified-source-field" }
quests[8732] = { id = 8732, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Field Duty Papers", progress = "Field duty papers?  What manner of nonsense is this, {name}?", completion = "In the old days I would've marked your forehead with the creature's blood to mark your accomplishment here.  Thrall insists we comply with the Druids' requests.\n\nHere, take these papers and go back to Cenarion Hold.  I'm sure they will have suitable work for you." }
quests[8733] = { id = 8733, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eranikus, Tyrant of the Dream", description = "This is a journey of redemption, hero. Would it be that I was slain today, I would have died for a just and righteous cause. You must recover the green scepter shard. You must cleanse Eranikus of the taint placed upon him by the Old Gods.\n\nTravel to Darnassus. Just outside the city walls you will find one of my agents. This agent will set things in motion for us and inform Tyrande of our plans without alerting Staghelm.\n\n<Malfurion sighs.>\n\nA fall from grace a thousand years in the making...", sourceObjective = "Travel to the continent of Teldrassil and find Malfurion's agent somewhere outside the walls of Darnassus.", completion = "The wisp is silent except for a low humming sound. Oddly enough, it is able to communicate with you through thoughts.", sourceObjectiveStatus = "unverified-source-field" }
quests[8734] = { id = 8734, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tyrande and Remulos", description = "Tyrande will be notifed, mortal. Shan'do Stormrage has prepared me for this contingency.\n\nNow you must venture to the Moonglade and speak with Remulos. He will have further instruction as to the summoning of Eranikus.\n\nWe all wish you great luck.", sourceObjective = "Travel to the Moonglade and speak to Keeper Remulos.", completion = "It would be impossible to pull Eranikus from the Dream should he refuse. His intentions, however, require him to enter our world. He seeks to destroy the living manifestation of Malfurion. To do this successfully would mean an end to one of the most powerful allies of the Dream. The Nightmare would wholly consume all that would remain should Malfurion fall...", sourceObjectiveStatus = "unverified-source-field" }
quests[8735] = { id = 8735, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Nightmare's Corruption", description = "You must travel to the four dream portals of Azeroth. From each you must draw a fragment of the Nightmare's corruption. The dragonkin that inhabit these areas will hold such fragments. Return to me when you have gathered these fragments.", sourceObjective = "Travel to the four Emerald Dream portals in Azeroth and collect a Fragment of the Nightmare's Corruption from each. Return to Keeper Remulos in the Moonglade when you have completed this task.", progress = "<Remulos is lost deep in thought.>", completion = "Are you prepared? Is the world prepared for what we are about to invoke? I do not know... I am bound by duty to Malfurion. Duty and honor...", sourceObjectiveStatus = "unverified-source-field" }
quests[8736] = { id = 8736, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Nightmare Manifests", description = "We must use restraint against Eranikus. We are to redeem him not destroy him.\n\nTyrande is already en route to assist us in this task. We must weather the dragon's blows and save Nighthaven from certain destruction.\n\nBe on guard! You and your allies are our only hope.", sourceObjective = "Defend Nighthaven from Eranikus. Do not let Keeper Remulos perish. Do not slay Eranikus. Defend yourself. Await Tyrande.", completion = "He is redeemed, {name}. He now returns to the Dream to right what he alone has done wrong. Eranikus will be a powerful ally to Malfurion and my father.\n\nThese armaments are for you, {name}; given to me by Ysera herself. You would do well to make use of them in your battles against the Qiraji.", sourceObjectiveStatus = "unverified-source-field" }
quests[8737] = { id = 8737, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Azure Templar", description = "The Twilight's Hammer and the elemental nobles they worship present a formidable threat to our operations in Silithus.  With the new enemies we're facing inside Ahn'Qiraj, we cannot afford to lower our guard to our enemies outside.\n\nFind a way to summon and destroy an Azure Templar and report to Bor Wildmane.", sourceObjective = "Summon and slay an Azure Templar and report back to Bor Wildmane in Cenarion Hold. You must also bring Tactical Task Briefing I in order to complete this quest.", progress = "Is your task done yet, {name}?", completion = "Good job, {name}.  Here's your next assignment.", sourceObjectiveStatus = "unverified-source-field" }
quests[8738] = { id = 8738, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hive'Regal Scout Report", description = "We've sent our best scouts deep into the silithid hives to gather intelligence.  Scout Landion has been watching the silithid movements at Hive'Regal for several days now.  Find him and obtain a written report.  We need to be able to act on that information as soon as possible, {name}.", sourceObjective = "Contact Cenarion Scout Landion inside Hive'Regal and return the Hive'Regal Scout Report to Windcaller Proudhorn at Cenarion Hold. You must also bring Tactical Task Briefing VII in order to complete this quest.", progress = "You'll find Scout Landion inside Hive'Regal.  Hurry, {name}!  Time is of the essence.", completion = "Your efforts are greatly appreciated, {name}.  I'll read these scouting reports right away, feel free to go over your next assignment.", sourceObjectiveStatus = "unverified-source-field" }
quests[8739] = { id = 8739, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hive'Ashi Scout Report", description = "We've sent our best scouts deep into the silithid hives to gather intelligence.  Scout Jalia has been watching the silithid movements at Hive'Ashi for several days now.  Find her and obtain a written report.  We need to be able to act on that information as soon as possible, {name}.", sourceObjective = "Contact Cenarion Scout Jalia inside Hive'Ashi and return the Hive'Ashi Scout Report to Windcaller Proudhorn at Cenarion Hold. You must also bring Tactical Task Briefing VIII in order to complete this quest.", progress = "You'll find Scout Jalia inside Hive'Ashi.  Hurry, {name}!  Time is of the essence.", completion = "Your efforts are greatly appreciated, {name}.  I'll read these scouting reports right away, feel free to go over your next assignment.", sourceObjectiveStatus = "unverified-source-field" }
quests[8740] = { id = 8740, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Twilight Marauders", description = "Bands of mounted Twilight's Hammer cultists have been spotted riding outside the reach of our forces in Cenarion Hold, picking off our smaller patrols and caravans.\n\nFind and defeat the twilight marauders along with their leader, a terrible warrior by the name of Morna.  Report to Windcaller Proudhorn after completing the task.", sourceObjective = "Slay Twilight Marauder Morna and 2 Twilight Marauders. Report to Windcaller Proudhorn when your task is finished. You must also bring Tactical Task Briefing IX in order to complete this quest.", progress = "Is your task done yet, {name}?", completion = "Well done, {name}.  The twilight marauders were inflicting an unacceptable number of casualties on our patrols.  Here's your next assignment.", sourceObjectiveStatus = "unverified-source-field" }
quests[8741] = { id = 8741, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Champion Returns", description = "The keeper awaits your return, {name}. Take the green scepter shard to Anachronos at the Caverns of Time.", sourceObjective = "Take the Green Scepter Shard to Anachronos at the Caverns of Time in Tanaris.", progress = "<Anachronos nods.>", completion = "Your deeds will be known to all, champion. They will sing your praises from Orgrimmar to the far reaches of the South Seas. All will know of the champion of the Bronze Flight, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[8742] = { id = 8742, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Might of Kalimdor", sourceObjective = "A thousand years has passed and just as it was fated, one stands before me. One who shall lead their people to a new age.\n\nThe Old God trembles, {name}. Oh yes, it fears your faith. Shatter the prophecy of C'Thun.\n\nIt knows you come, champion - and with you comes the might of Kalimdor. You have only to let me know when you are prepared and I shall grant you the Scepter of the Shifting Sands.", sourceObjectiveStatus = "unverified-source-field" }
quests[8743] = { id = 8743, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bang a Gong!", progress = "The Scarab Gong looms ominously before you. Steel yourself, {name}; for once The Scarab Gong is rung, the gates of Ahn'Qiraj will be opened.\n\nFrom the slackened maw of the beast can only come chaos and destruction. Defend your people!", completion = "From the ground near the gong springs a special crystal. Perhaps favor from the Brood." }
quests[8744] = { id = 8744, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Carefully Wrapped Present", sourceObjective = "The tag on this present reads:\n\nTo {name},\n\nMay your feast of Great-Winter be merry and bright!", sourceObjectiveStatus = "unverified-source-field" }
quests[8745] = { id = 8745, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Treasure of the Timeless One", sourceObjective = "Greetings, champion. I am Jonathan, keeper of the sacred gong and eternal watcher of the Bronze Flight.\n\nI have been empowered by the Timeless One himself to grant you an item of your choosing from his timeless treasure trove. May it aid you in your battles against C'Thun.", sourceObjectiveStatus = "unverified-source-field" }
quests[8746] = { id = 8746, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Metzen the Reindeer", description = "DISASTER has struck!  Metzen the Reindeer has been kidnapped!\n\nMetzen is one of Great-father Winter's eight reindeer - and property of Smokywood Pastures.  We believe he was carried off by that dastardly Abominable Greench, hiding out in Hillsbrad Foothills.  With the holiday season well under way, we're strapped to the coin box here!  Please - find Metzen, defeat his captors, and return him to us!", sourceObjective = "Rescue Metzen the Reindeer from his captors near Growless Cave in the Hillsbrad Foothills.", progress = "{name}!  Did you find him?  Were the notes in the satchel I gave you enough information to locate Metzen?  I hate to think of that those cruel thugs might do to him... but there's no way we can afford to pay such an exorbitant ransom!", completion = "You did it!  Huzzah!\n\nMetzen flew back into Great-father Winter's stables - yes Metzen can really fly - just a little while ago!  The dust worked like a charm; I knew it would.  You've saved the Feast of Winter Veil as well as Smokywood Pastures from disaster.  Thank you, {name}.\n\nListen... because of what you've done here, I want you to have this.  It's something VERY special; if you have a mount, I think you'll get a kick out of it.  Happy Winter Veil!", sourceObjectiveStatus = "unverified-source-field" }
quests[8747] = { id = 8747, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Path of the Protector", sourceObjective = "Impressive, little one. You have gone through much trouble to gain the favor of the Bronze Flight. Your dedication is noted.\n\nThe signet ring of the defender will offer superior protection against the forces of evil.\n\nBe warned, once you have chosen your path, you will have no recourse should you change your mind.", sourceObjectiveStatus = "unverified-source-field" }
quests[8748] = { id = 8748, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Path of the Protector", progress = "Your continued defense of the children of Kalimdor has been acknowledged. Hand me your signet ring so that I may enhance its powers.", completion = "Your rise amongst the rank of the Brood is most impressive, {name}. May you never stray from the path of the protector!" }
quests[8749] = { id = 8749, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Path of the Protector", progress = "You honor my kind, {name}. Strike down the enemies of Kalimdor! Show them what it means to deface the land of eternal starlight.\n\nYou have earned another enhancement. Hand me your signet ring so that I may bolster its power.", completion = "Your rise amongst the rank of the Brood is most impressive, {name}. May you never stray from the path of the protector!" }
quests[8750] = { id = 8750, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Path of the Protector", progress = "Dedication of this magnitude is a rarity. You have shown that your will is unfaltering, {name}. You shall be greatly rewarded for your stalwart watch over our world.\n\nHand me your signet ring so that I may strengthen its enchantment.", completion = "Your rise amongst the rank of the Brood is most impressive, {name}. May you never stray from the path of the protector!" }
quests[8751] = { id = 8751, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Protector of Kalimdor", progress = "Never have I seen such tenacity! The Bronze Flight grants you one final enchantment. The Timeless One himself has requested it so!\n\nHand me your signet ring so that I may make the necessary adjustments.", completion = "Rise, Protector of Kalimdor! Rise and be recognized!" }
quests[8752] = { id = 8752, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Path of the Conqueror", sourceObjective = "Impressive, little one. You have gone through much trouble to gain the favor of the Bronze Flight. Your dedication is noted.\n\nThe signet ring of the conqueror will greatly enhance your physical attacks.\n\nBe warned, once you have chosen your path, you will have no recourse should you change your mind.", sourceObjectiveStatus = "unverified-source-field" }
quests[8753] = { id = 8753, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Path of the Conqueror", progress = "Your continued defense of the children of Kalimdor has been acknowledged. Hand me your signet ring so that I may enhance its powers.", completion = "Your rise amongst the rank of the Brood is most impressive, {name}. May you never stray from the path of the conqueror!" }
quests[8754] = { id = 8754, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Path of the Conqueror", progress = "You honor my kind, {name}. Strike down the enemies of Kalimdor! Show them what it means to deface the land of eternal starlight.\n\nYou have earned another enhancement. Hand me your signet ring so that I may bolster its power.", completion = "Your rise amongst the rank of the Brood is most impressive, {name}. May you never stray from the path of the conqueror!" }
quests[8755] = { id = 8755, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Path of the Conqueror", progress = "Dedication of this magnitude is a rarity. You have shown that your will is unfaltering, {name}. You shall be greatly rewarded for your stalwart watch over our world.\n\nHand me your signet ring so that I may strengthen its enchantment.", completion = "Your rise amongst the rank of the Brood is most impressive, {name}. May you never stray from the path of the conqueror!" }
quests[8756] = { id = 8756, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Qiraji Conqueror", progress = "Never have I seen such tenacity! The Bronze Flight grants you one final enchantment. The Timeless One himself has requested it so!\n\nHand me your signet ring so that I may make the necessary adjustments.", completion = "Rise, Qiraji Conqueror! Rise and be recognized!" }
quests[8757] = { id = 8757, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Path of the Invoker", sourceObjective = "Impressive, little one. You have gone through much trouble to gain the favor of the Bronze Flight. Your dedication is noted.\n\nThe signet ring of the invoker will greatly enhance your magical and natural abilities.\n\nBe warned, once you have chosen your path, you will have no recourse should you change your mind.", sourceObjectiveStatus = "unverified-source-field" }
quests[8758] = { id = 8758, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Path of the Invoker", progress = "Your continued defense of the children of Kalimdor has been acknowledged. Hand me your signet ring so that I may enhance its powers.", completion = "Your rise amongst the rank of the Brood is most impressive, {name}. May you never stray from the path of the invoker!" }
quests[8759] = { id = 8759, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Path of the Invoker", progress = "You honor my kind, {name}. Strike down the enemies of Kalimdor! Show them what it means to deface the land of eternal starlight.\n\nYou have earned another enhancement. Hand me your signet ring so that I may bolster its power.", completion = "Your rise amongst the rank of the Brood is most impressive, {name}. May you never stray from the path of the invoker!" }
quests[8760] = { id = 8760, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Path of the Invoker", progress = "Dedication of this magnitude is a rarity. You have shown that your will is unfaltering, {name}. You shall be greatly rewarded for your stalwart watch over our world.\n\nHand me your signet ring so that I may strengthen its enchantment.", completion = "Your rise amongst the rank of the Brood is most impressive, {name}. May you never stray from the path of the invoker!" }
quests[8761] = { id = 8761, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Grand Invoker", progress = "Never have I seen such tenacity! The Bronze Flight grants you one final enchantment. The Timeless One himself has requested it so!\n\nHand me your signet ring so that I may make the necessary adjustments.", completion = "Rise, Grand Invoker! Rise and be recognized!" }
quests[8762] = { id = 8762, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Metzen the Reindeer", description = "DISASTER has struck!  Metzen the Reindeer has been kidnapped!\n\nMetzen is one of Great-father Winter's eight reindeer - and property of Smokywood Pastures.  We believe he was carried off by that dastardly Abominable Greench, hiding out in Hillsbrad Foothills.  With the holiday season well under way, we're strapped to the coin box here!  Please - find Metzen, defeat his captors, and return him to us!", sourceObjective = "Rescue Metzen the Reindeer from his captors near Growless Cave in Hillsbrad Foothills.", progress = "{name}!  Were the notes in the satchel I gave you enough information to locate Metzen?  I hate to think of that those cruel thugs might do to him... but there's no way we can afford to pay such an exorbitant ransom!", completion = "You did it!  Huzzah!\n\nMetzen flew back into Greatfather Winter's stables - yes Metzen can really fly - just a little while ago!  The dust worked like a charm; I knew it would.  You've saved the Feast of Winter Veil as well as Smokywood Pastures from disaster.  Thank you, {name}.\n\nListen... because of what you've done here, I want you to have this.  It's something VERY special; if you have a mount, I think you'll get a kick out of it.  Happy Winter Veil!", sourceObjectiveStatus = "unverified-source-field" }
quests[8763] = { id = 8763, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Hero of the Day", description = "Listen... I'm not really supposed to be telling you this, but since you're the hero of the day and all...\n\nThere's fresh holly everywhere this time of the year, but it never lasts.  We've got a machine that preserves holly - it never goes bad!  We use it to spice up the holiday... and profits during the summer!\n\nI'll let you use the preserver, but only if you're a master cook.  You'll need some deeprock salt and two, three, oh let's say five gold.  It'll net you a nice batch that's yours to keep.", sourceObjective = "Bring 1 Deeprock Salt and 5 gold coins to any Holly Preserver machine, upon which you will receive 5 Preserved Holly.", progress = "The \"Holly Preserver\" machine looks like some sort of still at first, but a careful examination of it reveals some goblin-esque changes to it.  Still, your skill at cooking seems to allow you to understand how the machine works.\n\nThere is already fresh holly in the machine - you simply need to provide some deeprock salt and five gold coins to get the machine working.", completion = "The machine lets off a little rumble and a small amount of steam as it starts working.  It is not too long thereafter until it stops, heralded by another small jet of steam erupting from it.  A door hatch opens, revealing a batch of preserved holly!", sourceObjectiveStatus = "unverified-source-field" }
quests[8764] = { id = 8764, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Changing of Paths - Protector No More", progress = "Champion, should you decide to walk another path, present me with your signet ring and a mountain of scarabs from our enemies in Ahn'Qiraj.", completion = "Be well, {name}. If you change your mind, I shall be here to assist you." }
quests[8765] = { id = 8765, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Changing of Paths - Invoker No More", progress = "Champion, should you decide to walk another path, present me with your signet ring and a mountain of scarabs from our enemies in Ahn'Qiraj.", completion = "Be well, {name}. If you change your mind, I shall be here to assist you." }
quests[8766] = { id = 8766, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Changing of Paths - Conqueror No More", progress = "Champion, should you decide to walk another path, present me with your signet ring and a mountain of scarabs from our enemies in Ahn'Qiraj.", completion = "Be well, {name}. If you change your mind, I shall be here to assist you." }
quests[8767] = { id = 8767, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Gently Shaken Gift", sourceObjective = "This present looks like it has been shaken a few times. The tag on it reads:\n\nTo a very special {race} {class}.", sourceObjectiveStatus = "unverified-source-field" }
quests[8768] = { id = 8768, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Gaily Wrapped Present", sourceObjective = "This festively-wrapped present has your name on it.\n\nWait, did it just move?", sourceObjectiveStatus = "unverified-source-field" }
quests[8769] = { id = 8769, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Ticking Present", sourceObjective = "Have a joyous Feast of Great-Winter from your friends at Smokeywood Pastures.", sourceObjectiveStatus = "unverified-source-field" }
quests[8770] = { id = 8770, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Target: Hive'Ashi Defenders", description = "As the war effort mounts, the silithid presence in the area presents an ever increasing threat to our operations.  You've been selected to partake on an assault on Hive'Ashi where your primary target will consist of Hive'Ashi defenders.\n\nReport back to Commander Mar'alith after your task is completed.", sourceObjective = "Slay 30 Hive'Ashi Defenders and report back to Commander Mar'alith at Cenarion Hold in Silithus. You must also bring Combat Task Briefing I in order to complete this quest.", progress = "You have something to tell me, {class}?", completion = "Excellent work, {name}.  Your diligence is as noteworthy as always.", sourceObjectiveStatus = "unverified-source-field" }
quests[8771] = { id = 8771, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Target: Hive'Ashi Sandstalkers", description = "As the war effort mounts, the silithid presence in the area presents an ever increasing threat to our operations.  You've been selected to partake on an assault on Hive'Ashi where your primary target will consist of Hive'Ashi sandstalkers.\n\nReport back to Commander Mar'alith after your task is completed.", sourceObjective = "Slay 30 Hive'Ashi Sandstalkers and report back to Commander Mar'alith at Cenarion Hold in Silithus. You must also bring Combat Task Briefing II in order to complete this quest.", progress = "You have something to tell me, {class}?", completion = "Excellent work, {name}.  Your part in the attack on Hive'Ashi has been noted.", sourceObjectiveStatus = "unverified-source-field" }
quests[8772] = { id = 8772, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Target: Hive'Zora Waywatchers", description = "Reinforcements have been called on to join the assault on Hive'Zora.  You have been selected to target Hive'Zora waywatchers.  Report back to Commander Mar'alith after completing your task.", sourceObjective = "Slay 30 Hive'Zora Waywatchers and report back to Commander Mar'alith at Cenarion Hold in Silithus. You must also bring Combat Task Briefing VI in order to complete this quest.", progress = "You have something to tell me, {class}?", completion = "Excellent work, {name}.  Your part in the attack on Hive'Zora has been noted.", sourceObjectiveStatus = "unverified-source-field" }
quests[8773] = { id = 8773, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Target: Hive'Zora Reavers", description = "Reinforcements have been called on to join the assault on Hive'Zora.  You have been selected to target Hive'Zora reavers.  Report back to Commander Mar'alith after completing your task.", sourceObjective = "Slay 30 Hive'Zora Reavers and report back to Commander Mar'alith at Cenarion Hold in Silithus. You must also bring Combat Task Briefing IV in order to complete this quest.", progress = "You have something to tell me, {class}?", completion = "I've heard good things about your part in the Hive'Zora attack.  Keep up the good work and victory will soon be ours.", sourceObjectiveStatus = "unverified-source-field" }
quests[8774] = { id = 8774, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Target: Hive'Regal Ambushers", description = "As the war effort mounts, the silithid presence in the area presents an ever increasing threat to our operations.  You've been selected to partake on an assault on Hive'Regal where your primary target will consist of the Hive'Regal ambushers.\n\nReport back to Commander Mar'alith after your task is completed.", sourceObjective = "Kill 30 Hive'Regal Ambushers and report back to Commander Mar'alith at Cenarion Hold in Silithus. You must also bring Combat Task Briefing VIII in order to complete this quest.", progress = "You wish to tell me something, {name}?", completion = "Excellent work, {name}.  Your part in the attack on Hive'Regal has been noted.", sourceObjectiveStatus = "unverified-source-field" }
quests[8775] = { id = 8775, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Target: Hive'Regal Spitfires", description = "As the war effort mounts, the silithid presence in the area presents an ever increasing threat to our operations.  You've been selected to partake on an assault on Hive'Regal where your primary target will consist of the airborne Hive'Regal spitfires.\n\nReport back to Commander Mar'alith after your task is completed.", sourceObjective = "Kill 30 Hive'Regal Spitfires and report back to Commander Mar'alith at Cenarion Hold in Silithus. You must also bring Combat Task Briefing IX in order to complete this quest.", progress = "You wish to tell me something, {name}?", completion = "Excellent work, {name}.  Your part in the attack on Hive'Regal has been noted.", sourceObjectiveStatus = "unverified-source-field" }
quests[8776] = { id = 8776, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Target: Hive'Regal Slavemakers", description = "As the war effort mounts, the silithid presence in the area presents an ever increasing threat to our operations.  You've been selected to partake on an assault on Hive'Regal where your primary target will consist of the Hive'Regal slavemakers.\n\nReport back to Commander Mar'alith after your task is completed.", sourceObjective = "Kill 30 Hive'Regal Slavemakers and report back to Commander Mar'alith at Cenarion Hold in Silithus. You must also bring Combat Task Briefing X in order to complete this quest.", progress = "You wish to tell me something, {name}?", completion = "Excellent work, {name}.  Your part in the attack on Hive'Regal has been noted.", sourceObjectiveStatus = "unverified-source-field" }
quests[8777] = { id = 8777, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Target: Hive'Regal Burrowers", description = "As the war effort mounts, the silithid presence in the area presents an ever increasing threat to our operations.  You've been selected to partake on an assault on Hive'Regal where your primary target will consist of Hive'Regal burrowers.\n\nReport back to Commander Mar'alith after your task is completed.", sourceObjective = "Kill 30 Hive'Regal Burrowers and report back to Commander Mar'alith at Cenarion Hold in Silithus. You must also bring Combat Task Briefing XI in order to complete this quest.", progress = "You wish to tell me something, {name}?", completion = "Excellent work, {name}.  Your part in the attack on Hive'Regal has been noted.", sourceObjectiveStatus = "unverified-source-field" }
quests[8778] = { id = 8778, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Ironforge Brigade Needs Explosives!", description = "The Ironforge Brigade has put in an unusual request for highly... volatile... components.  Gather them and bring them to Mr. Nozzlespring from the Ironforge Brigade.", sourceObjective = "Bring 6 Oils of Immolation, 5 Goblin Rocket Fuel and 10 Dense Blasting Powder to Arcanist Nozzlespring near Hive'Zora in Silithus. You must also bring Logistics Task Briefing IV in order to complete this quest.", progress = "You have something for me, {name}?", completion = "Ah, yes!  These will come in handy!  Much obliged, {name}!", sourceObjectiveStatus = "unverified-source-field" }
quests[8779] = { id = 8779, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Scrying Materials", description = "Geologist Larksbane's studies have proven to be of tremendous value to our operations in Silithus.  She has recently requested scrying materials to be used in her research.\n\nPlease gather these materials and deliver them to her directly so that she may continue her research.", sourceObjective = "Bring 1 Large Brilliant Shard, 1 Large Radiant Shard and 1 Huge Emerald to Geologist Larksbane at Cenarion Hold in Silithus. You must also bring Logistics Task Briefing V in order to complete this quest.", progress = "You have something for me, {name}?", completion = "Why, yes... these will be of tremendous aid!  These materials are awfully hard to come by in the desert, {name}.  Thank you.", sourceObjectiveStatus = "unverified-source-field" }
quests[8780] = { id = 8780, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Armor Kits for the Field", description = "The Ironforge Brigade's supply of armor kits in the battlefield is running dangerously low.  Obtain a batch and deliver them to Janela Stouthammer at the Ironforge Brigade's outpost outside Hive'Zora.", sourceObjective = "Bring 8 Rugged Armor Kits and 8 Heavy Armor Kits to Janela Stouthammer at the Ironforge Brigade Outpost near Hive'Zora in Silithus. You must also bring Logistics Task Briefing VII in order to complete this quest.", progress = "You have something for me, {name}?", completion = "Thanks, I'll hand these out to the lads.", sourceObjectiveStatus = "unverified-source-field" }
quests[8781] = { id = 8781, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Arms for the Field", description = "The Ironforge Brigade has been a worthy ally in our fight in Silithus.  Unfortunately, many of their supplies were lost on their way here.  Procure a batch of weapons and deliver them to Janela Stouthammer near Hive'Zora.", sourceObjective = "Bring 2 Moonsteel Broadswords to Janela Stouthammer at the Ironforge Brigade Outpost outside of Hive'Zora. You must also bring Logistics Task Briefing VI in order to complete this quest.", progress = "You have something for me, {name}?", completion = "Oh, excellent!  I won't have to hear complaints about dull blades anymore.  Thank you, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[8782] = { id = 8782, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Uniform Supplies", description = "The latest influx of volunteers has caused a shortage of uniforms.  Procure a batch of uniform materials and bring them to Windcaller Proudhorn.", sourceObjective = "Bring 1 Mooncloth, 2 Bolts of Runecloth and 1 Ironweb Spider Silk to Windcaller Proudhorn at Cenarion Hold in Silithus. You must also bring Logistics Task Briefing VIII in order to complete this quest.", progress = "You have something for me, {name}?", completion = "Ah, we were in need of these.  Your work is appreciated, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[8783] = { id = 8783, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Extraordinary Materials", description = "Vargus, Cenarion Hold's blacksmith, has requested enchanted materials to be used in the crafting of powerful weapons for our forces.  Obtain these and bring them directly to Vargus so that Cenarion Hold's troops may continue to be well equipped.", sourceObjective = "Bring 2 Enchanted Thorium Bars and 2 Enchanted Leather to Vargus at Cenarion Hold in Silithus. You must also bring Logistics Task Briefing IX in order to complete this quest.", progress = "You have something for me, {name}?", completion = "Ah, yes.  These materials are of excellent quality.  Thank you, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[8784] = { id = 8784, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Secrets of the Qiraji", description = "You have discovered an ancient Qiraji artifact! Perhaps one of the dragons near the entrance of the temple would have a use for this relic.", sourceObjective = "Take the Ancient Qiraji Artifact to the dragons hiding near the entrance of the temple.", progress = "You're glowing! I know what that means...", completion = "An exceptional find, {name}. Simply marvelous! This will definitely give us some insight into our enemy's twisted minds.", sourceObjectiveStatus = "unverified-source-field" }
quests[8785] = { id = 8785, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Orgrimmar Legion Needs Mojo!", description = "The Orgrimmar Legion has put in a request for several unusual ingredients.  Given their current performance in Silithus, we'd like to comply with their request as soon as possible.  Gather the materials and bring them to the troll called Shai.", sourceObjective = "Bring 6 Powerful Mojo, 6 Flasks of Big Mojo and 8 Oils of Immolation to Shadow Priestess Shai near Hive'Regal in Silithus. You must also bring Logistics Task Briefing IV in order to complete this quest.", progress = "Do you have my materials, {name}?", completion = "Ah, yes.  Just what I needed!  I'll make a special concoction with this.  The silithid won't like it one bit!", sourceObjectiveStatus = "unverified-source-field" }
quests[8786] = { id = 8786, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Arms for the Field", description = "The Orgrimmar Legion has put in a request for additional weapons that we haven't been able to provide at the moment.  Obtain the weapons they've requested and bring them to Merok Longstride outside of Hive'Regal.", sourceObjective = "Bring 3 Massive Iron Axes to Merok Longstride at the Orgrimmar Legion camp outside of Hive'Regal. You must also bring Logistics Task Briefing VI in order to complete this quest.", progress = "You have something for me, {name}?", completion = "Excellent work.  We were in short supply of these, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[8787] = { id = 8787, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Armor Kits for the Field", description = "The brave volunteers of the Orgrimmar Legion have arrived to Silithus to aid us in our cause.  Their supplies of armor kits were somehow lost in the trip.  Obtain a batch of armor kits and deliver them to Merok Longstride at the location of the Orgrimmar Legion camp.", sourceObjective = "Bring 8 Rugged Armor Kits and 8 Heavy Armor Kits to Merok Longstride near Hive'Regal. You must also bring Logistics Task Briefing VII in order to complete this quest.", progress = "You have something for me, {name}?", completion = "Ah, yes... I will distribute these to the troops, {name}.  The Orgrimmar Legion thanks you!", sourceObjectiveStatus = "unverified-source-field" }
quests[8788] = { id = 8788, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Gently Shaken Gift", sourceObjective = "This present looks like it has been shaken a few times. The tag on it reads:\n\nTo a very special {race} {class}.", sourceObjectiveStatus = "unverified-source-field" }
quests[8789] = { id = 8789, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Imperial Qiraji Armaments", description = "We have not sat idly by for a millennium, {name}.\n\nWe have watched these beasts feast on their own when they have exhausted their utility. We have listened as they have plotted and schemed to destroy our world. And we have learned of their own internal treachery.\n\nWeaknesses exist and we know how to use those weaknesses to our advantage.\n\nFind and bring me their ceremonial armaments: Combined with the element created from the volatility of their own God, they will become a force of reckoning.", sourceObjective = "Arygos in the Temple of Ahn'Qiraj will create Elementium Infused Armaments for you should you bring him Imperial Qiraji Armaments and 3 Elementium Ingots.", progress = "Seek out what I requested. You will become greater than the sum of your parts, champion.", completion = "Infused with Elementium, these weapons will cut through the Qiraji and their God with incredible ease.", sourceObjectiveStatus = "unverified-source-field" }
quests[8790] = { id = 8790, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Imperial Qiraji Regalia", description = "Arygos theorizes that the element which is born of conflicts between the Old Gods and their minions is also extremely deadly to them under the right conditions. I speak of Elementium, mortal.\n\nFind and bring me Imperial Qiraji Regalia and the toxic element and I shall infuse weapons of great power.", sourceObjective = "Merithra of the Dream in the Temple of Ahn'Qiraj will create Elementium Infused Armaments for you should you bring her Imperial Qiraji Regalia and 3 Elementium Ingots.", progress = "You will strike them down and free us of these bonds.", completion = "Use the item well, {name}. Let them feel the pain that they so dearly wish to inflict upon others.", sourceObjectiveStatus = "unverified-source-field" }
quests[8791] = { id = 8791, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Fall of Ossirian", description = "A terrible menace has been laid to rest. The cruel Ossirian has been vanquished.\n\nThe denizens of Kalimdor would be relieved to know of this victory. Take Ossirian's head and present it to Commander Mar'alith of Cenarion Hold.", sourceObjective = "Deliver the Head of Ossirian the Unscarred to Commander Mar'alith at Cenarion Hold in Silithus.", progress = "Ah, {name}, you have returned! And in one piece, I might add. What news do you bring from Ahn'Qiraj?", completion = "I offer you my highest commendation and your choice of an item of power, {name}. You have done the people of Kalimdor a great service.", sourceObjectiveStatus = "unverified-source-field" }
quests[8792] = { id = 8792, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Horde Needs Your Help!", description = "Hello, I'm glad that you've decided to hear me out. The Horde needs all of the help that it can get to prepare for the Ahn'Qiraj War, and that means that we need you! Even now as we speak, official collectors are gathering the necessary material needed for the upcoming war, but we won't be able to meet our goals without your assistance, {name}!\n\nYou should go speak with the guy in charge, Warlord Gorchuk. What do you say, {class}? Will you help out with the vital preparations?", sourceObjective = "Speak with Warlord Gorchuk in Orgrimmar's Valley of Spirits.", completion = "Throm'ka, {class}! Good to see so many of the Horde, such as yourself, {name}, coming out to lend your support in laying the groundwork for the upcoming Ahn'Qiraj War. The effort here will ensure that we are victorious against the Silithid and their evil masters hidden away inside Ahn'Qiraj.\n\nSo now that you are here, be sure to speak with the various collectors and offer your assistance in gathering those materials that you are suited to.", sourceObjectiveStatus = "unverified-source-field" }
quests[8793] = { id = 8793, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Horde Needs Your Help!", description = "Hello, I'm glad that you've decided to hear me out. The Horde needs all of the help that it can get to prepare for the Ahn'Qiraj War, and that means that we need you! Even now as we speak, official collectors are gathering the necessary material needed for the upcoming war, but we won't be able to meet our goals without your assistance, {name}!\n\nYou should go speak with the guy in charge, Warlord Gorchuk. What do you say, {class}? Will you help out with the vital preparations?", sourceObjective = "Speak with Warlord Gorchuk in Orgrimmar's Valley of Spirits.", completion = "Throm'ka, {class}! Good to see so many of the Horde, such as yourself, {name}, coming out to lend your support in laying the groundwork for the upcoming Ahn'Qiraj War. The effort here will ensure that we are victorious against the Silithid and their evil masters hidden away inside Ahn'Qiraj.\n\nSo now that you are here, be sure to speak with the various collectors and offer your assistance in gathering those materials that you are suited to.", sourceObjectiveStatus = "unverified-source-field" }
quests[8794] = { id = 8794, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Horde Needs Your Help!", description = "Hello, I'm glad that you've decided to hear me out. The Horde needs all of the help that it can get to prepare for the Ahn'Qiraj War, and that means that we need you! Even now as we speak, official collectors are gathering the necessary material needed for the upcoming war, but we won't be able to meet our goals without your assistance, {name}!\n\nYou should go speak with the guy in charge, Warlord Gorchuk. What do you say, {class}? Will you help out with the vital preparations?", sourceObjective = "Speak with Warlord Gorchuk in Orgrimmar's Valley of Spirits.", completion = "Throm'ka, {class}! Good to see so many of the Horde, such as yourself, {name}, coming out to lend your support in laying the groundwork for the upcoming Ahn'Qiraj War. The effort here will ensure that we are victorious against the Silithid and their evil masters hidden away inside Ahn'Qiraj.\n\nSo now that you are here, be sure to speak with the various collectors and offer your assistance in gathering those materials that you are suited to.", sourceObjectiveStatus = "unverified-source-field" }
quests[8795] = { id = 8795, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Alliance Needs Your Help!", description = "Hello, I'm glad that you've decided to hear me out. The Alliance needs all of the help that it can get to prepare for the Ahn'Qiraj War, and that means that we need you! Even now as we speak, official collectors are gathering the necessary material needed for the upcoming war, but we won't be able to meet our goals without your assistance, {name}!\n\nYou should go speak with the guy in charge, Field Marshal Snowfall. What do you say, {class}? Will you help out with the vital preparations?", sourceObjective = "Speak with Field Marshal Snowfall in Ironforge's Military Ward.", completion = "Hail and well met lad! Good to see so many of the Alliance, such as yourself, {name}, coming out to lend your support in laying the groundwork for the upcoming Ahn'Qiraj War. The effort here will ensure that we are victorious against the Silithid and their evil masters hidden away inside Ahn'Qiraj.\n\nSo now that you are here, be sure to speak with the various collectors and offer your assistance in gathering those materials that you are suited to.", sourceObjectiveStatus = "unverified-source-field" }
quests[8796] = { id = 8796, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Alliance Needs Your Help!", description = "Hello, I'm glad that you've decided to hear me out. The Alliance needs all of the help that it can get to prepare for the Ahn'Qiraj War, and that means that we need you! Even now as we speak, official collectors are gathering the necessary material needed for the upcoming war, but we won't be able to meet our goals without your assistance, {name}!\n\nYou should go speak with the guy in charge, Field Marshal Snowfall. What do you say, {class}? Will you help out with the vital preparations?", sourceObjective = "Speak with Field Marshal Snowfall in Ironforge's Military Ward.", completion = "Hail and well met lad! Good to see so many of the Alliance, such as yourself, {name}, coming out to lend your support in laying the groundwork for the upcoming Ahn'Qiraj War. The effort here will ensure that we are victorious against the Silithid and their evil masters hidden away inside Ahn'Qiraj.\n\nSo now that you are here, be sure to speak with the various collectors and offer your assistance in gathering those materials that you are suited to.", sourceObjectiveStatus = "unverified-source-field" }
quests[8797] = { id = 8797, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Alliance Needs Your Help!", description = "Hello, I'm glad that you've decided to hear me out. The Alliance needs all of the help that it can get to prepare for the Ahn'Qiraj War, and that means that we need you! Even now as we speak, official collectors are gathering the necessary material needed for the upcoming war, but we won't be able to meet our goals without your assistance, {name}!\n\nYou should go speak with the guy in charge, Field Marshal Snowfall. What do you say, {class}? Will you help out with the vital preparations?", sourceObjective = "Speak with Field Marshal Snowfall in Ironforge's Military Ward.", completion = "Hail and well met lad! Good to see so many of the Alliance, such as yourself, {name}, coming out to lend your support in laying the groundwork for the upcoming Ahn'Qiraj War. The effort here will ensure that we are victorious against the Silithid and their evil masters hidden away inside Ahn'Qiraj.\n\nSo now that you are here, be sure to speak with the various collectors and offer your assistance in gathering those materials that you are suited to.", sourceObjectiveStatus = "unverified-source-field" }
quests[8798] = { id = 8798, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Yeti of Your Own", sourceObjective = "Say! You know what?! You're an engineer too! So, since you helped me teach my friends a lesson, I'm going to teach you how to make your very own mechanical yeti! Now the fun can go on forever and ever, and you can scare whoever you want! Provided that you can scare up the components to make it that is.\n\nWhat do you say, {name}? Do you want to learn the secret to making a mechanical yeti?", sourceObjectiveStatus = "unverified-source-field" }
quests[8799] = { id = 8799, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Hero of the Day", description = "Listen... I'm not really supposed to be telling you this, but since you're the hero of the day and all...\n\nThere's fresh holly everywhere this time of the year, but it never lasts.  We've got a machine that preserves holly - it never goes bad!  We use it to spice up the holiday... and profits during the summer!\n\nI'll let you use the preserver, but only if you're a master cook.  You'll need some deeprock salt and two, three, oh let's say five gold.  It'll net you a nice batch that's yours to keep.", sourceObjective = "Bring 1 Deeprock Salt and 5 gold coins to the Holly Preserver machine, upon which you will receive 5 Preserved Holly.", progress = "The \"Holly Preserver\" machine looks like some sort of still at first, but a careful examination of it reveals some goblin-esque changes to it.  Still, your skill at cooking seems to allow you to understand how the machine works.\n\nThere is already fresh holly in the machine - you simply need to provide some deeprock salt and five gold coins to get the machine working.", completion = "The machine lets off a little rumble and a small amount of steam as it starts working.  It is not too long thereafter until it stops, heralded by another small jet of steam erupting from it.  A door hatch opens, revealing a batch of preserved holly!", sourceObjectiveStatus = "unverified-source-field" }
quests[8800] = { id = 8800, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Cenarion Battlegear", description = "As you complete the tasks you're assigned in the war you'll want to talk to Vargus, the blacksmith.  Show him any badges you've earned along the way. He'll provide you with gear to match your level of commitment to our cause.", sourceObjective = "Talk to Vargus at Cenarion Hold in Silithus.", completion = "Kaldon sent you?  Very well, let's see what we can do for you.", sourceObjectiveStatus = "unverified-source-field" }
quests[8801] = { id = 8801, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "C'Thun's Legacy", description = "The walls of Ahn'Qiraj tremble. A force of evil, older than the world itself, has been destroyed.\n\nAs you look at the remnants of the colossal abomination your heart nearly freezes. Even in death you can feel the legacy of C'Thun's evil around you.\n\nYou have done what was thought to be impossible.\n\nYou grab at an eye stalk of the fiend, stowing it safely in your pack.\n\nTake the Eye of C'Thun to the dragons in the next chamber.", sourceObjective = "Take the Eye of C'Thun to Caelastrasz in the Temple of Ahn'Qiraj.", progress = "<Caelastrasz kneels before you.>\n\nLord {name}, you have freed us of its grasp.", completion = "We will leave this place on our own, Lord {name} - once we are certain that the evil within has been wholly destroyed. Your journey of legend is almost at an end.", sourceObjectiveStatus = "unverified-source-field" }
quests[8802] = { id = 8802, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Savior of Kalimdor", description = "To the Caverns of Time you go, <Lord/Lady> {name}. Anachronos awaits your return. Give him the eye of C'Thun as he will undoubtedly wish to place it in his master's collection.", sourceObjective = "Take the Eye of C'Thun to Anachronos at the Caverns of Time.", progress = "Lord {name}! It is over...", completion = "The Master has left these for you, champion. From the timeless cache: A collection of artifacts spanning thousands of years - the choice is yours.", sourceObjectiveStatus = "unverified-source-field" }
quests[8803] = { id = 8803, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Festive Gift", sourceObjective = "The note on this present reads:\n\nTo {name},\n\nIn hoping this will help you spread warm tidings and holiday cheer to all of Azeroth.\n\nFrom Greatfather Winter", sourceObjectiveStatus = "unverified-source-field" }
quests[8804] = { id = 8804, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Desert Survival Kits", description = "With the arrival of fresh recruits to Cenarion Hold comes the problem of keeping them alive in the desert.  Dehydration as well as numerous poisonous creatures present a serious threat to inexperienced volunteers.  Gather the supplies necessary for a desert survival kit and bring them to Calandrath in Cenarion Hold.", sourceObjective = "Bring 4 Globes of Water, 4 Powerful Anti-Venom and 4 Smoked Desert Dumplings to Calandrath at the inn in Cenarion Hold in Silithus. You must also bring Logistics Task Briefing I in order to complete this quest.", progress = "You have something for me?", completion = "Excellent!  We were in need of these, {name}.  Thanks.", sourceObjectiveStatus = "unverified-source-field" }
quests[8805] = { id = 8805, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Boots for the Guard", description = "The mounted division of the Cenarion Hold guard is in short supply of ornate mithril boots.  Procure a batch and deliver them immediately to Captain Vish Kozus in Cenarion Hold.", sourceObjective = "Bring 3 Ornate Mithril Boots to Vish Kozus, Captain of the Guard at Cenarion Hold in Silithus. You must also bring Logistics Task Briefing II in order to complete this quest.", progress = "You have something for me?", completion = "Excellent.  We were in need of these, {name}.  Good work.", sourceObjectiveStatus = "unverified-source-field" }
quests[8806] = { id = 8806, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Grinding Stones for the Guard", description = "The Cenarion Hold guard is in short supply of grinding stones.  Procure a batch and deliver them immediately to Captain Vish Kozus in Cenarion Hold.", sourceObjective = "Bring 10 Dense Grinding Stones, 10 Solid Grinding Stones and 10 Heavy Grinding Stones to Vish Kozus, Captain of the Guard at Cenarion Hold in Silithus. You must also bring Logistics Task Briefing III in order to complete this quest.", progress = "You have something for me?", completion = "Excellent.  We were in need of these, {name}.  Good work.", sourceObjectiveStatus = "unverified-source-field" }
quests[8807] = { id = 8807, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Scrying Materials", description = "Geologist Larksbane's studies have proven to be of tremendous value to our operations in Silithus.  She has recently requested scrying materials to be used in her research.\n\nPlease gather these materials and deliver them to her directly so that she may continue her research.", sourceObjective = "Bring 1 Large Brilliant Shard, 1 Large Radiant Shard and 1 Huge Emerald to Geologist Larksbane at Cenarion Hold in Silithus. You must also bring Logistics Task Briefing V in order to complete this quest.", progress = "You have something for me, {name}?", completion = "Why yes... these will be of tremendous aid!  These materials are awfully hard to come by in the desert, {name}.  Thank you.", sourceObjectiveStatus = "unverified-source-field" }
quests[8808] = { id = 8808, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Uniform Supplies", description = "The latest influx of volunteers has caused a shortage of uniforms.  Procure a batch of uniform materials and bring them to Windcaller Proudhorn.", sourceObjective = "Bring 1 Mooncloth, 2 Bolts of Runecloth and 1 Ironweb Spider Silk to Windcaller Proudhorn at Cenarion Hold in Silithus. You must also bring Logistics Task Briefing VIII in order to complete this quest.", progress = "You have something for me, {name}?", completion = "Ah, we were in need of these.  Your work is appreciated, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[8809] = { id = 8809, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Extraordinary Materials", description = "Vargus, Cenarion Hold's blacksmith, has requested enchanted materials to be used in the crafting of powerful weapons for our forces.  Obtain these and bring them directly to Vargus so that Cenarion Hold's troops may continue to be well equipped.", sourceObjective = "Bring 2 Enchanted Thorium Bars and 2 Enchanted Leather to Vargus at Cenarion Hold in Silithus. You must also bring Logistics Task Briefing IX in order to complete this quest.", progress = "You have something for me, {name}?", completion = "Ah, yes.  These materials are of excellent quality.  Thank you, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[8810] = { id = 8810, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bandages for the Field", description = "Our supply of bandages in the battlefield is running dangerously low after the recent casualties we have incurred.  Obtain a batch of first-aid supplies and deliver them to Windcaller Proudhorn in Cenarion Hold.", sourceObjective = "Bring 30 Heavy Runecloth Bandages, 30 Heavy Silk Bandages and 30 Heavy Mageweave Bandages to Windcaller Proudhorn at Cenarion Hold in Silithus. You must also bring Logistics Task Briefing X in order to complete this quest.", progress = "You have something for me, {name}?", completion = "Just in time.  These supplies will save lives, {name}.  Your work is appreciated.  Here's your next assignment.", sourceObjectiveStatus = "unverified-source-field" }
quests[8811] = { id = 8811, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "One Commendation Signet", progress = "For those adventurers who have but a single commendation signet, I'll exchange it for a small amount of recognition with Darnassus.\n\nPlease bear in mind that it is better to hand over a stack of ten signets at once; your efforts will receive greater recognition in doing so.  We offer a single signet exchange as a service for those who don't have enough for a full stack of ten.\n\nWith that being said, I stand ready to assist you if you still wish to hand in a single signet.", completion = "Very well - your deeds have been entered into the records, and you are duly recognized for your efforts.  Keep up the good work, {class}.\n\nIf you have any more signets to hand in, then I am able to assist you further in that regard." }
quests[8812] = { id = 8812, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "One Commendation Signet", progress = "For those adventurers who have but a single commendation signet, I'll exchange it for a small amount of recognition with the Gnomeregan Exiles.\n\nPlease bear in mind that it is better to hand over a stack of ten signets at once; your efforts will receive greater recognition in doing so.  We offer a single signet exchange as a service for those who don't have enough for a full stack of ten.\n\nWith that being said, I stand ready to assist you if you still wish to hand in a single signet.", completion = "Very well - your deeds have been entered into the records, and you are duly recognized for your efforts.  Keep up the good work, {class}.\n\nIf you have any more signets to hand in, then I am able to assist you further in that regard." }
quests[8813] = { id = 8813, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "One Commendation Signet", progress = "For those adventurers who have but a single commendation signet, I'll exchange it for a small amount of recognition with Ironforge.\n\nPlease bear in mind that it is better to hand over a stack of ten signets at once; your efforts will receive greater recognition in doing so.  We offer a single signet exchange as a service for those who don't have enough for a full stack of ten.\n\nWith that being said, I stand ready to assist you if you still wish to hand in a single signet.", completion = "Very well - your deeds have been entered into the records, and you are duly recognized for your efforts.  Keep up the good work, {class}.\n\nIf you have any more signets to hand in, then I am able to assist you further in that regard." }
